'use client';

import Link from 'next/link';
import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, Bell, CalendarDays, Check, ChevronDown, ChevronRight,
  CircleDollarSign, ClipboardList, Clock3, Command, Computer, CreditCard, FileText, Headphones, House,
  Laptop, LayoutDashboard, LifeBuoy, ListFilter, MapPin, Menu, MessageCircle, MoreHorizontal, PackageCheck,
  PanelLeftClose, Plus, Search, Settings, ShieldCheck, Smartphone, Sparkles, Store, Users, Wrench, X,
} from 'lucide-react';
import {
  type Appointment, type Client, type Device, type Mode, type Order, type Status, type View,
  dateLabel, DEMO_DATE, hasConflict, initials, isLate, money, newCode, nextStatus, normalize, nowLabel, statuses,
} from '@/lib/demo';
import { useDemo } from '@/components/demo-provider';
import { QuoteDialog } from '@/components/quote-dialog';
import { PaymentDialog } from '@/components/payment-dialog';
import { AppointmentDialog } from '@/components/appointment-dialog';
import { AppointmentDrawer } from '@/components/appointment-drawer';
import { OperationalHealth } from '@/components/operational-health';
import { hasSupabaseConfig } from '@/lib/supabase/env';

const navItems: { key: View; label: string; icon: typeof LayoutDashboard; group?: string }[] = [
  { key: 'painel', label: 'Painel', icon: LayoutDashboard },
  { key: 'ordens', label: 'Ordens de serviço', icon: ClipboardList, group: 'Operação' },
  { key: 'clientes', label: 'Clientes', icon: Users },
  { key: 'equipamentos', label: 'Equipamentos', icon: Laptop },
  { key: 'agenda', label: 'Agenda', icon: CalendarDays },
  { key: 'orcamentos', label: 'Orçamentos', icon: FileText, group: 'Gestão' },
  { key: 'financeiro', label: 'Financeiro', icon: CircleDollarSign },
  { key: 'configuracoes', label: 'Configurações', icon: Settings, group: 'Sistema' },
];
const viewTitles: Record<View, { title: string; description: string; eyebrow: string }> = {
  painel: { title: 'Bom dia, Marina', description: 'Aqui está o que merece atenção hoje na Matriz · Centro.', eyebrow: 'Segunda-feira, 28 de setembro de 2026' },
  ordens: { title: 'Ordens de serviço', description: 'Acompanhe cada atendimento do recebimento à entrega.', eyebrow: 'Operação' },
  clientes: { title: 'Clientes', description: 'Histórico, contatos e equipamentos em um só lugar.', eyebrow: 'Relacionamento' },
  equipamentos: { title: 'Equipamentos', description: 'Identifique e encontre rapidamente tudo que passou pela assistência.', eyebrow: 'Ativos' },
  agenda: { title: 'Agenda da equipe', description: 'Organize visitas, sessões remotas e retiradas sem sobreposição.', eyebrow: 'Operação' },
  orcamentos: { title: 'Orçamentos', description: 'Propostas que aguardam resposta e histórico de aprovações.', eyebrow: 'Gestão' },
  financeiro: { title: 'Financeiro', description: 'Visão simples dos valores a receber e dos recebimentos registrados.', eyebrow: 'Gestão' },
  configuracoes: { title: 'Configurações', description: 'Ajustes da assistência, equipe e preferências da operação.', eyebrow: 'Sistema' },
};
const modeIcon: Record<Mode, typeof Store> = { Balcão: Store, Remoto: Headphones, Domicílio: House };

function IconButton({ label, onClick, children, className = '' }: { label: string; onClick?: () => void; children: React.ReactNode; className?: string }) { return <button className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick}>{children}</button>; }
function ModePill({ mode }: { mode: Mode }) { const Icon = modeIcon[mode]; return <span className={`mode-pill mode-${normalize(mode)}`}><Icon size={14} />{mode}</span>; }
function StatusPill({ status, late = false }: { status: Status; late?: boolean }) { return <span className={`status-pill status-${normalize(status)} ${late ? 'late' : ''}`}><span className="status-dot" />{late ? 'Atrasada · ' : ''}{status}</span>; }
function Avatar({ name, small = false }: { name: string; small?: boolean }) { return <span className={`avatar ${small ? 'small' : ''}`} aria-label={name}>{initials(name)}</span>; }
function PageHeading({ view, onNew }: { view: View; onNew: () => void }) { const { title, description, eyebrow } = viewTitles[view]; return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="heading-actions"><button className="button ghost hide-mobile"><span>⌘</span> Atalhos</button>{view !== 'configuracoes' && <button className="button primary" onClick={onNew}><Plus size={18} /> Novo atendimento</button>}</div></div>; }

export function Workspace({ view: initialView }: { view: View }) {
  const { data, ready, notify, reset } = useDemo();
  const liveMode = hasSupabaseConfig();
  const [liveResources, setLiveResources] = useState<{ clients: Client[]; devices: Device[]; orders: Order[]; appointments: Appointment[]; quotes: Array<{ id: string; serviceOrderId: string; version: number; status: string; totalCents: number; validUntil: string | null }> } | null>(null);
  const [liveLoading, setLiveLoading] = useState(false);
  const [view, setView] = useState(initialView);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  const [modal, setModal] = useState<'order' | 'client' | 'device' | 'quote' | 'payment' | 'appointment' | null>(null);
  const refreshLiveResources = useCallback(async () => {
    if (!liveMode) return;
    setLiveLoading(true);
    try {
      const [clientsResponse, devicesResponse, ordersResponse, quotesResponse, appointmentsResponse] = await Promise.all([fetch('/api/clients'), fetch('/api/devices'), fetch('/api/orders'), fetch('/api/quotes'), fetch('/api/appointments')]);
      if (!clientsResponse.ok || !devicesResponse.ok || !ordersResponse.ok || !quotesResponse.ok || !appointmentsResponse.ok) { setLiveResources(null); return; }
      const clientsPayload = await clientsResponse.json() as { data?: Array<{ id: string; full_name: string; phone: string; email?: string | null }> };
      const devicesPayload = await devicesResponse.json() as { data?: Array<{ id: string; client_id: string; code: string; kind: string; brand: string; model: string; serial?: string | null; notes?: string | null }> };
      const ordersPayload = await ordersResponse.json() as { data?: Array<{ id: string; number: string; client_id: string; device_id?: string | null; mode: Mode; status: Status; priority: string; issue: string; accessories?: string | null; due_date?: string | null; amount_cents: number; paid_cents: number }> };
      const quotesPayload = await quotesResponse.json() as { data?: Array<{ id: string; service_order_id: string; version: number; status: string; total_cents: number; valid_until?: string | null }> };
      const appointmentsPayload = await appointmentsResponse.json() as { data?: Array<{ id: string; service_order_id: string; client_id: string; mode: Mode; title: string; start_at: string; end_at: string }> };
      setLiveResources({
        clients: (clientsPayload.data ?? []).map(client => ({ id: client.id, name: client.full_name, phone: client.phone, email: client.email ?? '', address: '' })),
        devices: (devicesPayload.data ?? []).map(item => ({ id: item.id, clientId: item.client_id, code: item.code, kind: item.kind, brand: item.brand, model: item.model, serial: item.serial ?? '', notes: item.notes ?? '' })),
        orders: (ordersPayload.data ?? []).map(order => ({ id: order.id, number: order.number, clientId: order.client_id, deviceId: order.device_id ?? '', mode: order.mode, status: order.status, priority: order.priority, technician: 'Equipe', issue: order.issue, due: order.due_date ?? DEMO_DATE, amount: order.amount_cents, paid: order.paid_cents, accessories: order.accessories ?? '', history: [], contacts: [] })),
        appointments: (appointmentsPayload.data ?? []).map(appointment => { const start = new Date(appointment.start_at); const end = new Date(appointment.end_at); return { id: appointment.id, orderId: appointment.service_order_id, date: start.toISOString().slice(0, 10), time: start.toTimeString().slice(0, 5), duration: Math.max(15, Math.round((end.getTime() - start.getTime()) / 60000)), technician: 'Equipe', title: appointment.title, mode: appointment.mode, address: '' }; }),
        quotes: (quotesPayload.data ?? []).map(quote => ({ id: quote.id, serviceOrderId: quote.service_order_id, version: quote.version, status: quote.status, totalCents: quote.total_cents, validUntil: quote.valid_until ?? null })),
      });
    } catch { setLiveResources(null); }
    finally { setLiveLoading(false); }
  }, [liveMode]);
  useEffect(() => { const timer = window.setTimeout(() => { void refreshLiveResources(); }, 0); return () => window.clearTimeout(timer); }, [refreshLiveResources]);
  const resourceData = liveResources ? { ...data, clients: liveResources.clients, devices: liveResources.devices, orders: liveResources.orders } : data;
  const clientName = (id: string) => resourceData.clients.find(c => c.id === id)?.name ?? 'Cliente não encontrado';
  const device = (id: string) => resourceData.devices.find(d => d.id === id);
  function navigate(next: View) { setView(next); setMobileOpen(false); setSearch(''); window.history.replaceState(null, '', next === 'painel' ? '/' : `/${next}`); }
  function openOrder(order: Order) { setSelectedOrder(order); }
  function onNew() { setModal('order'); }
  return <div className="app-shell">
    <Sidebar active={view} onNavigate={navigate} mobileOpen={mobileOpen} onClose={() => setMobileOpen(false)} reset={reset} />
    <div className="main-shell">
      <header className="topbar"><div className="mobile-brand"><span className="brand-mark small-mark">N</span><b>Nexo</b></div><IconButton label="Abrir menu" className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={21} /></IconButton><div className="global-search"><Search size={17} /><input aria-label="Buscar no sistema" placeholder="Buscar cliente, OS ou equipamento" value={search} onChange={event => setSearch(event.target.value)} /><kbd>⌘ K</kbd></div><div className="topbar-actions"><button className="unit-switcher"><span className="unit-icon"><Store size={16} /></span><span className="hide-mobile">Matriz · Centro</span><ChevronDown size={15} /></button><IconButton label="Notificações"><Bell size={19} /><span className="notification-dot" /></IconButton><div className="user-profile"><Avatar name="Marina Azevedo" small /><span className="user-meta"><b>Marina Azevedo</b><small>Gestora</small></span><ChevronDown size={15} /></div></div></header>
      <main className="content"><PageHeading view={view} onNew={onNew} />{!ready && <div className="loading-bar" aria-label="Carregando demonstração" />}<SearchResults query={search} data={resourceData} onOrder={openOrder} onClient={client => { notify(`Cliente ${client.name} selecionado.`); navigate('clientes'); }} />{view === 'painel' && <Dashboard data={resourceData} clientName={clientName} device={device} appointmentsOverride={liveResources?.appointments ?? null} onOrder={openOrder} onNavigate={navigate} onNew={onNew} />}{view === 'ordens' && <OrdersView data={resourceData} search={search} clientName={clientName} device={device} onOrder={openOrder} onNew={onNew} />}{view === 'clientes' && <ClientsView data={resourceData} search={search} clientsOverride={liveResources?.clients ?? null} devicesOverride={liveResources?.devices ?? null} liveLoading={liveLoading} onNew={() => setModal('client')} />}{view === 'equipamentos' && <DevicesView data={resourceData} search={search} clientName={clientName} devicesOverride={liveResources?.devices ?? null} clientsOverride={liveResources?.clients ?? null} liveLoading={liveLoading} onNew={() => setModal('device')} />}{view === 'agenda' && <AgendaView data={resourceData} clientName={clientName} appointmentsOverride={liveResources?.appointments ?? null} liveMode={Boolean(liveResources)} onNew={() => setModal('appointment')} onSelect={setSelectedAppointment} notify={notify} />}{view === 'orcamentos' && <QuotesView data={resourceData} clientName={clientName} quotesOverride={liveResources?.quotes ?? null} onOrder={openOrder} notify={notify} onNew={() => setModal('quote')} />}{view === 'financeiro' && <FinanceView data={resourceData} clientName={clientName} onOrder={openOrder} onNew={() => setModal('payment')} />}{view === 'configuracoes' && <SettingsView notify={notify} reset={reset} />}</main>
    </div>
    {selectedOrder && <OrderDrawer order={selectedOrder} data={resourceData} liveMode={Boolean(liveResources)} onUpdated={() => void refreshLiveResources()} close={() => setSelectedOrder(null)} notify={notify} />}
    {selectedAppointment && <AppointmentDrawer appointment={selectedAppointment} data={resourceData} liveMode={Boolean(liveResources)} onUpdated={() => void refreshLiveResources()} close={() => setSelectedAppointment(null)} notify={notify} />}
    {modal === 'order' && <NewOrderModal data={resourceData} liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'client' && <NewClientModal liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'device' && <NewDeviceModal data={resourceData} liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'quote' && <QuoteDialog orders={resourceData.orders} liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'payment' && <PaymentDialog orders={resourceData.orders} liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'appointment' && <AppointmentDialog orders={resourceData.orders} liveMode={Boolean(liveResources)} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}
  </div>;
}

function Sidebar({ active, onNavigate, mobileOpen, onClose, reset }: { active: View; onNavigate: (view: View) => void; mobileOpen: boolean; onClose: () => void; reset: () => void }) { return <><div className={`sidebar-backdrop ${mobileOpen ? 'visible' : ''}`} onClick={onClose} /><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="brand"><span className="brand-mark">N</span><span><b>Nexo</b><small>gestão da assistência</small></span><IconButton label="Fechar menu" className="sidebar-close" onClick={onClose}><PanelLeftClose size={18} /></IconButton></div><div className="demo-tag"><Sparkles size={14} /><span>Modo demonstração</span></div><nav>{navItems.map((item, index) => <div key={item.key}>{item.group && <span className="nav-group">{item.group}</span>}<button className={`nav-item ${active === item.key ? 'active' : ''}`} onClick={() => onNavigate(item.key)}><item.icon size={18} strokeWidth={active === item.key ? 2.3 : 1.8} /><span>{item.label}</span>{item.key === 'ordens' && <span className="nav-count">9</span>}</button>{index === 0 && <div className="nav-separator" />}</div>)}</nav><div className="sidebar-footer"><div className="help-card"><div className="help-icon"><LifeBuoy size={17} /></div><div><b>Precisa de ajuda?</b><span>Veja como funciona</span></div><ChevronRight size={16} /></div><button className="nav-item" onClick={() => { reset(); onClose(); }}><ShieldCheck size={18} /><span>Restaurar demonstração</span></button><div className="sidebar-version">v0.1 · etapa 1 <span>·</span> sem WhatsApp</div></div></aside></>; }

function SearchResults({ query, data, onOrder, onClient }: { query: string; data: ReturnType<typeof useDemo>['data']; onOrder: (order: Order) => void; onClient: (client: Client) => void }) { if (!query.trim() || query.trim().length < 2) return null; const q = normalize(query); const clients = data.clients.filter(c => normalize(c.name).includes(q) || normalize(c.phone).includes(q)).slice(0, 3); const orders = data.orders.filter(o => normalize(o.number).includes(q) || normalize(o.issue).includes(q)).slice(0, 3); if (!clients.length && !orders.length) return <div className="search-popover"><Search size={18} /><span>Nenhum resultado para <b>{query}</b></span></div>; return <div className="search-popover"><span className="popover-label">Resultados rápidos</span>{clients.map(client => <button key={client.id} onClick={() => onClient(client)}><Avatar name={client.name} small /><span><b>{client.name}</b><small>Cliente · {client.phone}</small></span><ChevronRight size={15} /></button>)}{orders.map(order => <button key={order.id} onClick={() => onOrder(order)}><span className="search-order">{order.number}</span><span><b>{data.clients.find(c => c.id === order.clientId)?.name}</b><small>OS · {order.status}</small></span><ChevronRight size={15} /></button>)}</div>; }

function Dashboard({ data, clientName, device, appointmentsOverride, onOrder, onNavigate, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; device: (id: string) => Device | undefined; appointmentsOverride?: Appointment[] | null; onOrder: (o: Order) => void; onNavigate: (v: View) => void; onNew: () => void }) { const late = data.orders.filter(isLate); const waiting = data.orders.filter(o => o.status === 'Aguardando aprovação'); const due = data.orders.filter(o => o.paid < o.amount && o.status !== 'Concluído'); const dueTotal = due.reduce((sum, o) => sum + o.amount - o.paid, 0); const today = (appointmentsOverride ?? data.appointments).filter(a => a.date === DEMO_DATE); return <div className="dashboard-grid"><section className="hero-card"><div className="hero-orb orb-one" /><div className="hero-orb orb-two" /><div className="hero-content"><span className="hero-kicker"><span className="pulse-dot" /> Visão da operação · atualizada agora</span><h2>Seu dia, <em>sob controle.</em></h2><p>Há <b>{late.length} atendimentos atrasados</b> e <b>{waiting.length} orçamentos</b> aguardando resposta.</p><div className="hero-actions"><button className="button light" onClick={() => onNavigate('ordens')}>Ver pendências <ArrowDownRight size={16} /></button><button className="text-button light-text" onClick={() => onNew()}>Abrir atendimento <Plus size={15} /></button></div></div><div className="hero-stat"><span>Receita em aberto</span><strong>{money(dueTotal)}</strong><small><ArrowUpRight size={14} /> 12,8% <i>vs. mês anterior</i></small></div></section><div className="metric-row"><Metric icon={<ClipboardList />} label="Em andamento" value={String(data.orders.filter(o => !['Concluído', 'Pronto para entrega'].includes(o.status)).length)} detail="+2 esta semana" trend="up" color="blue" /><Metric icon={<Clock3 />} label="Prazo vencido" value={String(late.length).padStart(2, '0')} detail="Requer atenção" trend="down" color="orange" /><Metric icon={<PackageCheck />} label="Prontos para entrega" value={String(data.orders.filter(o => o.status === 'Pronto para entrega').length).padStart(2, '0')} detail="Hoje" trend="neutral" color="green" /><Metric icon={<CircleDollarSign />} label="A receber" value={money(dueTotal)} detail="6 clientes" trend="up" color="purple" /></div><section className="panel recent-panel"><PanelHeader title="Acompanhe as OS" subtitle="Últimas movimentações" link="Ver todas" onLink={() => onNavigate('ordens')} /><div className="table-wrap"><table><thead><tr><th>Ordem</th><th>Cliente</th><th>Equipamento</th><th>Status</th><th>Responsável</th><th aria-label="Ações" /></tr></thead><tbody>{data.orders.slice(0, 5).map(order => <OrderRow key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</tbody></table></div><div className="mobile-order-list">{data.orders.slice(0, 5).map(order => <OrderCard key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</div></section><div className="bottom-grid"><section className="panel agenda-panel"><PanelHeader title="Agenda de hoje" subtitle={dateLabel(DEMO_DATE)} link="Abrir agenda" onLink={() => onNavigate('agenda')} /><div className="agenda-list">{today.map(item => <AppointmentItem key={item.id} appointment={item} />)}</div><button className="add-dashed" onClick={onNew}><Plus size={16} /> Adicionar compromisso</button></section><section className="panel attention-panel"><PanelHeader title="Atenção" subtitle="O que precisa de você" /><div className="attention-list"><AttentionItem icon={<FileText />} tone="violet" title={`${waiting.length} orçamentos sem resposta`} detail="O mais antigo há 2 dias" onClick={() => onNavigate('orcamentos')} /><AttentionItem icon={<AlertTriangle />} tone="orange" title={`${late.length} OS passaram do prazo`} detail="Verifique os responsáveis" onClick={() => onNavigate('ordens')} /><AttentionItem icon={<CircleDollarSign />} tone="green" title={`${due.length} recebimentos pendentes`} detail={`Total de ${money(dueTotal)}`} onClick={() => onNavigate('financeiro')} /></div></section></div></div>; }
function Metric({ icon, label, value, detail, trend, color }: { icon: React.ReactNode; label: string; value: string; detail: string; trend: string; color: string }) { return <div className="metric-card"><span className={`metric-icon ${color}`}>{icon}</span><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small className={trend === 'up' ? 'positive' : trend === 'down' ? 'negative' : ''}>{trend === 'up' && <ArrowUpRight size={13} />}{trend === 'down' && <ArrowDownRight size={13} />}{detail}</small></div><MoreHorizontal size={17} className="metric-more" /></div>; }
function PanelHeader({ title, subtitle, link, onLink }: { title: string; subtitle?: string; link?: string; onLink?: () => void }) { return <div className="panel-header"><div><h3>{title}</h3>{subtitle && <span>{subtitle}</span>}</div>{link && <button className="panel-link" onClick={onLink}>{link} <ChevronRight size={15} /></button>}</div>; }
function OrderRow({ order, clientName, device, onClick }: { order: Order; clientName: (id: string) => string; device?: Device; onClick: () => void }) { return <tr onClick={onClick} className="clickable-row"><td><b className="order-number">{order.number}</b><small className={isLate(order) ? 'late-text' : ''}>{isLate(order) ? `Venceu em ${dateLabel(order.due)}` : `Previsto para ${dateLabel(order.due)}`}</small></td><td><span className="person-cell"><Avatar name={clientName(order.clientId)} small /><b>{clientName(order.clientId)}</b></span></td><td><span className="device-cell"><Laptop size={15} />{device?.brand} {device?.model}</span><small className="code-label">{device?.code}</small></td><td><StatusPill status={order.status} late={isLate(order)} /></td><td><span className="person-cell"><Avatar name={order.technician} small /><b>{order.technician}</b></span></td><td><ChevronRight size={17} className="row-chevron" /></td></tr>; }
function OrderCard({ order, clientName, device, onClick }: { order: Order; clientName: (id: string) => string; device?: Device; onClick: () => void }) { return <button className="order-card" onClick={onClick}><div><span className="order-number">{order.number}</span><StatusPill status={order.status} late={isLate(order)} /></div><b>{clientName(order.clientId)}</b><span>{device?.brand} {device?.model} · {device?.code}</span><ChevronRight size={17} /></button>; }
function AppointmentItem({ appointment }: { appointment: Appointment }) { const Icon = modeIcon[appointment.mode]; return <div className="appointment-item"><span className="time-label">{appointment.time}</span><div className={`appointment-line ${normalize(appointment.mode)}`} /><div className="appointment-info"><div><b>{appointment.title}</b><ModePill mode={appointment.mode} /></div><span>{appointment.technician}{appointment.address && ` · ${appointment.address}`}</span></div><Icon size={17} className="appointment-type" /></div>; }
function AttentionItem({ icon, tone, title, detail, onClick }: { icon: React.ReactNode; tone: string; title: string; detail: string; onClick: () => void }) { return <button className="attention-item" onClick={onClick}><span className={`attention-icon ${tone}`}>{icon}</span><span><b>{title}</b><small>{detail}</small></span><ChevronRight size={16} /></button>; }

function OrdersView({ data, search, clientName, device, onOrder, onNew }: { data: ReturnType<typeof useDemo>['data']; search: string; clientName: (id: string) => string; device: (id: string) => Device | undefined; onOrder: (o: Order) => void; onNew: () => void }) { const [filter, setFilter] = useState<'all' | Status>('all'); const [mode, setMode] = useState<'list' | 'board'>('list'); const filtered = data.orders.filter(o => { const q = normalize(search); const matches = !q || [o.number, o.issue, clientName(o.clientId), device(o.deviceId)?.code ?? ''].some(value => normalize(value).includes(q)); return matches && (filter === 'all' || o.status === filter); }); return <div className="view-stack"><div className="view-toolbar"><div className="filter-pills"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>Todas <span>{data.orders.length}</span></button>{statuses.slice(0, 6).map(status => <button key={status} className={filter === status ? 'selected' : ''} onClick={() => setFilter(status)}>{status}<span>{data.orders.filter(o => o.status === status).length}</span></button>)}</div><div className="toolbar-actions"><button className="button secondary"><ListFilter size={16} /> Filtros</button><div className="segmented"><button className={mode === 'list' ? 'on' : ''} onClick={() => setMode('list')}><ClipboardList size={16} /></button><button className={mode === 'board' ? 'on' : ''} onClick={() => setMode('board')}><Activity size={16} /></button></div></div></div>{mode === 'list' ? <section className="panel full-panel"><div className="table-wrap"><table><thead><tr><th>Ordem</th><th>Cliente</th><th>Equipamento</th><th>Modalidade</th><th>Status</th><th>Responsável</th><th /></tr></thead><tbody>{filtered.map(order => <OrderRow key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</tbody></table></div><div className="mobile-order-list">{filtered.map(order => <OrderCard key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</div>{!filtered.length && <EmptyState title="Nenhuma OS encontrada" text="Ajuste os filtros ou abra um novo atendimento." action="Novo atendimento" onClick={onNew} />}</section> : <Board orders={filtered} clientName={clientName} device={device} onOrder={onOrder} />}</div>; }
function Board({ orders, clientName, device, onOrder }: { orders: Order[]; clientName: (id: string) => string; device: (id: string) => Device | undefined; onOrder: (o: Order) => void }) { return <div className="kanban">{statuses.slice(0, 6).map(status => <section className="kanban-column" key={status}><header><span className="kanban-title"><i className={`status-dot dot-${normalize(status)}`} />{status}</span><span>{orders.filter(o => o.status === status).length}</span></header>{orders.filter(o => o.status === status).map(order => <button className="kanban-card" key={order.id} onClick={() => onOrder(order)}><div><b>{order.number}</b>{order.priority === 'Alta' && <span className="priority-high">Alta</span>}</div><strong>{clientName(order.clientId)}</strong><span>{device(order.deviceId)?.brand} {device(order.deviceId)?.model}</span><footer><Avatar name={order.technician} small /><small>{order.technician}</small><span>{dateLabel(order.due)}</span></footer></button>)}<button className="kanban-add"><Plus size={14} /> Adicionar</button></section>)}</div>; }

function ClientsView({ data, search, clientsOverride, devicesOverride, liveLoading, onNew }: { data: ReturnType<typeof useDemo>['data']; search: string; clientsOverride?: Client[] | null; devicesOverride?: Device[] | null; liveLoading?: boolean; onNew: () => void }) { const q = normalize(search); const clients = (clientsOverride ?? data.clients).filter(c => !q || [c.name, c.phone, c.email].some(v => normalize(v).includes(q))); const devices = devicesOverride ?? data.devices; return <div className="view-stack"><div className="list-toolbar"><span>{liveLoading ? 'Carregando clientes…' : `${clients.length} clientes cadastrados`}</span><div><button className="button secondary"><ListFilter size={16} /> Filtrar</button><button className="button primary" onClick={onNew}><Plus size={17} /> Novo cliente</button></div></div><section className="panel full-panel"><div className="table-wrap"><table><thead><tr><th>Cliente</th><th>Contato</th><th>Equipamentos</th><th>Último atendimento</th><th>Status</th><th /></tr></thead><tbody>{clients.map(client => { const clientDevices = devices.filter(d => d.clientId === client.id); const last = data.orders.filter(o => o.clientId === client.id).sort((a, b) => b.id.localeCompare(a.id))[0]; return <tr className="clickable-row" key={client.id}><td><span className="person-cell"><Avatar name={client.name} /><span><b>{client.name}</b><small>{client.email}</small></span></span></td><td><span className="contact-cell"><span>{client.phone}</span><small>{client.address}</small></span></td><td><span className="device-count"><Laptop size={15} />{clientDevices.length} {clientDevices.length === 1 ? 'equipamento' : 'equipamentos'}</span>{clientDevices[0] && <small className="code-label">{clientDevices.map(d => d.code).join(' · ')}</small>}</td><td>{last ? <><b className="order-number">{last.number}</b><small>{dateLabel(last.due)}</small></> : <span className="muted">Ainda sem OS</span>}</td><td>{last ? <StatusPill status={last.status} /> : <span className="status-pill status-neutral"><span className="status-dot" />Novo</span>}</td><td><ChevronRight size={17} className="row-chevron" /></td></tr>; })}</tbody></table></div><div className="client-cards">{clients.map(client => <article className="client-card" key={client.id}><div className="client-card-head"><Avatar name={client.name} /><div><b>{client.name}</b><span>{client.phone}</span></div><MoreHorizontal size={18} /></div><div className="client-card-meta"><span><Laptop size={14} />{devices.filter(d => d.clientId === client.id).length} equipamentos</span><span>{data.orders.filter(o => o.clientId === client.id).length} OS</span></div></article>)}</div>{!clients.length && <EmptyState title="Nenhum cliente encontrado" text="Tente buscar por nome ou telefone." action="Novo cliente" onClick={onNew} />}</section></div>; }

function DevicesView({ data, search, clientName, devicesOverride, clientsOverride, liveLoading, onNew }: { data: ReturnType<typeof useDemo>['data']; search: string; clientName: (id: string) => string; devicesOverride?: Device[] | null; clientsOverride?: Client[] | null; liveLoading?: boolean; onNew: () => void }) { const q = normalize(search); const devicesSource = devicesOverride ?? data.devices; const clientsSource = clientsOverride ?? data.clients; const resolveClientName = (id: string) => clientsSource.find(c => c.id === id)?.name ?? clientName(id); const devices = devicesSource.filter(d => !q || [d.code, d.brand, d.model, resolveClientName(d.clientId)].some(v => normalize(v).includes(q))); return <div className="view-stack"><div className="list-toolbar"><span>{liveLoading ? 'Carregando equipamentos…' : `${devices.length} equipamentos identificados`}</span><div><button className="button secondary"><ListFilter size={16} /> Filtrar</button><button className="button primary" onClick={onNew}><Plus size={17} /> Novo equipamento</button></div></div><section className="device-grid">{devices.map(d => { const orders = data.orders.filter(o => o.deviceId === d.id); const current = orders[orders.length - 1]; return <article className="panel device-card" key={d.id}><div className="device-card-top"><span className="equipment-code">{d.code}</span><span className="device-card-actions">{devicesOverride && <Link href={`/equipamentos/${d.id}/etiqueta`} className="plain-icon" aria-label="Imprimir etiqueta"><FileText size={17} /></Link>}<button className="plain-icon" aria-label="Mais opções"><MoreHorizontal size={17} /></button></span></div><div className="device-visual"><Computer size={42} strokeWidth={1.25} /></div><div className="device-card-body"><span className="eyebrow">{d.kind}</span><h3>{d.brand} {d.model}</h3><p>{resolveClientName(d.clientId)}</p><div className="device-details"><span><span className="detail-label">Série</span>{d.serial}</span><span><span className="detail-label">Atendimentos</span>{orders.length}</span></div>{current && <div className="device-current"><span>Último atendimento</span><b>{current.number} · {current.status}</b></div>}</div></article>; })}</section>{!devices.length && <EmptyState title="Nenhum equipamento encontrado" text="Use o código de quatro caracteres, marca ou cliente." action="Novo equipamento" onClick={onNew} />}</div>; }

function AgendaView({ data, clientName, appointmentsOverride, liveMode = false, onNew, onSelect, notify }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; appointmentsOverride?: Appointment[] | null; liveMode?: boolean; onNew: () => void; onSelect?: (appointment: Appointment) => void; notify: (message: string, error?: boolean) => void }) { const [day, setDay] = useState(DEMO_DATE); const appointments = (appointmentsOverride ?? data.appointments).filter(a => a.date === day); return <div className="view-stack"><div className="agenda-toolbar"><div className="date-navigation"><button className="icon-button"><ChevronDown size={17} /></button><div><b>{day === DEMO_DATE ? 'Hoje' : 'Amanhã'}</b><span>{new Date(`${day}T12:00:00`).toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })}</span></div><button className="icon-button"><ChevronRight size={17} /></button></div><div className="toolbar-actions"><button className="button secondary"><Users size={16} /> Todos os técnicos</button><button className="button primary" onClick={onNew}><Plus size={17} /> Novo compromisso</button></div></div><div className="agenda-layout"><section className="panel calendar-panel"><div className="calendar-head"><div><b>Setembro 2026</b><span>Semana 40</span></div><div><button className="icon-button" onClick={() => setDay(DEMO_DATE)} aria-label="Voltar para hoje"><CalendarDays size={17} /></button><button className="icon-button" aria-label="Mais opções"><MoreHorizontal size={17} /></button></div></div><div className="week-grid">{['seg', 'ter', 'qua', 'qui', 'sex', 'sáb', 'dom'].map((d, i) => <button key={d} className={day === `2026-09-${28 + i}` ? 'active' : ''} onClick={() => setDay(`2026-09-${28 + i}`)}><span>{d}</span><b>{28 + i}</b></button>)}</div><div className="calendar-body">{['08:00', '09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00'].map(time => <div className="calendar-row" key={time}><span>{time}</span><div className="calendar-slot">{appointments.filter(a => a.time === time).map(a => <button className={`calendar-event ${normalize(a.mode)}`} key={a.id} onClick={() => onSelect ? onSelect(a) : notify(`${a.title} · ${clientName(data.orders.find(o => o.id === a.orderId)?.clientId ?? '')}${liveMode ? ' · agenda conectada' : ''}`)}><b>{a.title}</b><span>{a.technician} · {a.duration} min</span></button>)}</div></div>)}{!appointments.length && <div className="calendar-empty"><CalendarDays size={22} />Nenhum compromisso neste dia.</div>}</div></section><aside className="panel day-summary"><PanelHeader title="Resumo do dia" subtitle={`${appointments.length} compromissos`} />{appointments.map(a => <div className="summary-event" key={a.id}><span className={`summary-time ${normalize(a.mode)}`}>{a.time}</span><div><b>{a.title}</b><span>{clientName(data.orders.find(o => o.id === a.orderId)?.clientId ?? '')}</span><small>{a.technician} · {a.mode}</small></div></div>)}<button className="add-dashed" onClick={onNew}><Plus size={16} /> Novo compromisso</button></aside></div></div>; }

function QuotesView({ data, clientName, quotesOverride, onOrder, notify, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; quotesOverride?: Array<{ id: string; serviceOrderId: string; version: number; status: string; totalCents: number; validUntil: string | null }> | null; onOrder: (o: Order) => void; notify: (message: string, error?: boolean) => void; onNew?: () => void }) { const live = quotesOverride !== null && quotesOverride !== undefined; const liveQuotes = quotesOverride ?? []; const demoQuotes = data.orders.filter(o => ['Aguardando aprovação', 'Em execução', 'Concluído'].includes(o.status)); const approvalCount = live ? liveQuotes.filter(q => q.status === 'sent').length : data.orders.filter(o => o.status === 'Aguardando aprovação').length; const total = live ? liveQuotes.reduce((sum, q) => sum + q.totalCents, 0) : demoQuotes.reduce((sum, o) => sum + o.amount, 0); return <div className="view-stack"><div className="quote-summary"><div><span>Em aprovação</span><b>\${approvalCount}</b><small>aguardando retorno</small></div><div><span>Valor proposto</span><b>{money(total)}</b><small>em orçamentos ativos</small></div><div><span>Taxa de aprovação</span><b>—</b><small>dados reais em consolidação</small></div></div><section className="panel full-panel"><PanelHeader title="Propostas recentes" subtitle="Versões válidas e pendentes" link="Novo orçamento" onLink={onNew} /><div className="quote-list">{live ? liveQuotes.map(quote => { const order = data.orders.find(item => item.id === quote.serviceOrderId); return <div className="quote-row" key={quote.id}><button className="quote-main-action" style={{ flex: 1, minWidth: 0, border: 0, padding: 0, background: 'transparent', display: 'flex', alignItems: 'center', gap: 12, textAlign: 'left', color: 'inherit', cursor: 'pointer' }} onClick={() => order && onOrder(order)} disabled={!order}><span className="quote-icon"><FileText size={18} /></span><span className="quote-main"><b>{order?.number ?? 'OS vinculada'}</b><strong>{order ? clientName(order.clientId) : 'Cliente não encontrado'}</strong><small>Versão {quote.version} · {quote.validUntil ? 'válida até ' + dateLabel(quote.validUntil) : 'sem validade definida'}</small></span><span className="quote-value"><b>{money(quote.totalCents)}</b><small>valor total</small></span><span className="status-pill status-orange"><span className="status-dot" />{quote.status}</span></button><PortalLinkAction quoteId={quote.id} enabled={quote.status === 'sent'} notify={notify} /></div>; }) : demoQuotes.map(o => <button className="quote-row" key={o.id} onClick={() => onOrder(o)}><span className="quote-icon"><FileText size={18} /></span><span className="quote-main"><b>{o.number}</b><strong>{clientName(o.clientId)}</strong><small>Versão 1 · enviada em 26/09/2026</small></span><span className="quote-value"><b>{money(o.amount)}</b><small>Validade: 7 dias</small></span><StatusPill status={o.status} /><ChevronRight size={17} /></button>)}</div></section></div>; }

function PortalLinkAction({ quoteId, enabled, notify }: { quoteId: string; enabled: boolean; notify: (message: string, error?: boolean) => void }) { const [busy, setBusy] = useState(false); async function createLink() { if (!enabled || busy) return; setBusy(true); try { const response = await fetch(`/api/quotes/${quoteId}/portal-link`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ expiresInDays: 7 }) }); const result = await response.json() as { data?: { url: string }; error?: string }; if (!response.ok || !result.data?.url) { notify(result.error ?? 'Não foi possível gerar o link do portal.', true); return; } await navigator.clipboard.writeText(result.data.url); notify('Link de aprovação copiado para a área de transferência.'); } catch { notify('Não foi possível gerar o link do portal.', true); } finally { setBusy(false); } } return <button className="button secondary compact" type="button" disabled={!enabled || busy} onClick={event => { event.stopPropagation(); void createLink(); }}>{busy ? 'Gerando…' : 'Copiar link'}</button>; }
function FinanceView({ data, clientName, onOrder, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; onOrder: (o: Order) => void; onNew?: () => void }) { const open = data.orders.filter(o => o.amount > o.paid && o.status !== 'Concluído'); const received = data.orders.reduce((sum, o) => sum + o.paid, 0); return <div className="view-stack"><div className="finance-cards"><Metric icon={<CircleDollarSign />} label="A receber" value={money(open.reduce((s, o) => s + o.amount - o.paid, 0))} detail="em aberto" trend="up" color="purple" /><Metric icon={<CreditCard />} label="Recebido no mês" value={money(received)} detail="+8,4% vs. anterior" trend="up" color="green" /><Metric icon={<ArrowDownRight />} label="Em atraso" value={money(open.filter(isLate).reduce((s, o) => s + o.amount - o.paid, 0))} detail={`${open.filter(isLate).length} clientes`} trend="down" color="orange" /></div><section className="panel full-panel"><PanelHeader title="Valores pendentes" subtitle="Recebimentos registrados e saldo por OS" link="Registrar recebimento" onLink={onNew} /><div className="table-wrap"><table><thead><tr><th>OS</th><th>Cliente</th><th>Total</th><th>Recebido</th><th>Saldo</th><th>Situação</th><th /></tr></thead><tbody>{open.map(o => <tr className="clickable-row" key={o.id} onClick={() => onOrder(o)}><td><b className="order-number">{o.number}</b></td><td>{clientName(o.clientId)}</td><td>{money(o.amount)}</td><td>{money(o.paid)}</td><td><b>{money(o.amount - o.paid)}</b></td><td><span className={`status-pill ${isLate(o) ? 'late' : 'status-orange'}`}><span className="status-dot" />{isLate(o) ? 'Atrasado' : 'Pendente'}</span></td><td><ChevronRight size={17} /></td></tr>)}</tbody></table></div></section></div>; }
function SettingsView({ notify, reset }: { notify: (message: string, error?: boolean) => void; reset: () => void }) { const [saved, setSaved] = useState(false); return <div className="settings-layout"><div className="settings-nav"><button className="active"><Store size={17} /> Unidade</button><button><Users size={17} /> Equipe e permissões</button><button><Bell size={17} /> Notificações</button><button><ShieldCheck size={17} /> Segurança</button></div><section className="panel settings-panel"><div className="settings-section"><span className="eyebrow">Identidade da operação</span><h2>Como sua equipe reconhece a assistência</h2><p>Essas informações aparecem em documentos e na navegação da equipe.</p><div className="form-grid"><label>Nome da assistência<input defaultValue="Nexo Assistência" /></label><label>Unidade ativa<input defaultValue="Matriz · Centro" /></label><label>Telefone principal<input defaultValue="(11) 3333-1010" /></label><label>Fuso horário<select defaultValue="America/Sao_Paulo"><option value="America/Sao_Paulo">Brasília (GMT−3)</option></select></label></div></div><div className="settings-section"><span className="eyebrow">Preferências de operação</span><h2>O que a equipe vê primeiro</h2><div className="preference"><span><b>Alertar conflitos na agenda</b><small>Impedir confirmação sem tratar sobreposição de horários.</small></span><button className="toggle on" aria-label="Alertar conflitos ativado"><span /></button></div><div className="preference"><span><b>Exigir justificativa ao entregar com saldo pendente</b><small>Registrar a decisão do gestor no histórico da OS.</small></span><button className="toggle on" aria-label="Exigir justificativa ativado"><span /></button></div></div><OperationalHealth notify={notify} /><div className="settings-footer"><button className="button secondary" onClick={() => { reset(); notify('Demonstração restaurada com sucesso.'); }}>Restaurar demonstração</button><button className="button primary" onClick={() => { setSaved(true); notify('Preferências salvas apenas nesta demonstração.'); setTimeout(() => setSaved(false), 3000); }}>{saved ? <><Check size={17} /> Salvo</> : 'Salvar alterações'}</button></div></section></div>; }

function EmptyState({ title, text, action, onClick }: { title: string; text: string; action: string; onClick: () => void }) { return <div className="empty-state"><span className="empty-icon"><Search size={22} /></span><h3>{title}</h3><p>{text}</p><button className="button primary" onClick={onClick}><Plus size={16} /> {action}</button></div>; }

function OrderDrawer({ order, data, liveMode = false, onUpdated, close, notify }: { order: Order; data: ReturnType<typeof useDemo>['data']; liveMode?: boolean; onUpdated?: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { const client = data.clients.find(c => c.id === order.clientId); const device = data.devices.find(d => d.id === order.deviceId); const { commit } = useDemo(); const [tab, setTab] = useState<'overview' | 'history'>('overview'); const [saving, setSaving] = useState(false); const [history, setHistory] = useState(order.history); const loadDetails = useCallback(async () => { if (!liveMode) return; try { const response = await fetch(`/api/orders/${order.id}`); if (!response.ok) return; const result = await response.json() as { data?: { events?: Array<{ description: string; created_at: string }> } }; setHistory((result.data?.events ?? []).map(event => ({ text: event.description, at: new Date(event.created_at).toLocaleString('pt-BR') }))); } catch { /* preserve current drawer state when details are unavailable */ } }, [liveMode, order.id]); useEffect(() => { const timer = window.setTimeout(() => { void loadDetails(); }, 0); return () => window.clearTimeout(timer); }, [loadDetails]); const next = nextStatus(order); async function advance() { if (!next) return notify('Esta OS já está na última etapa.'); setSaving(true); if (liveMode) { try { const response = await fetch(`/api/orders/${order.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: next }) }); const result = await response.json() as { error?: string }; if (!response.ok) return notify(result.error ?? 'Não foi possível atualizar a OS.', true); notify(`OS ${order.number} atualizada para ${next}.`); onUpdated?.(); close(); } catch { notify('Não foi possível conectar ao servidor.', true); } finally { setSaving(false); } return; } commit(current => ({ ...current, orders: current.orders.map(o => o.id === order.id ? { ...o, status: next, history: [...o.history, { text: `Etapa atualizada para ${next}.`, at: nowLabel() }] } : o) }), `OS ${order.number} atualizada para ${next}.`); setSaving(false); close(); } return <><div className="drawer-backdrop" onClick={close} /><aside className="order-drawer"><header><div><span className="eyebrow">Ordem de serviço</span><h2>{order.number}</h2></div><IconButton label="Fechar detalhes" onClick={close}><X size={20} /></IconButton></header><div className="drawer-scroll"><div className="drawer-title-row"><StatusPill status={order.status} late={isLate(order)} /><ModePill mode={order.mode} />{order.priority === 'Alta' && <span className="priority-high">Prioridade alta</span>}</div><div className="drawer-client"><Avatar name={client?.name ?? ''} /><div><b>{client?.name}</b><span>{client?.phone} · {client?.email}</span></div><button className="button secondary compact" onClick={() => notify('Canal de contato copiado para a área de transferência.')}> <MessageCircle size={15} /> Contatar</button></div><div className="drawer-tabs"><button className={tab === 'overview' ? 'active' : ''} onClick={() => setTab('overview')}>Resumo</button><button className={tab === 'history' ? 'active' : ''} onClick={() => setTab('history')}>Histórico <span>{history.length}</span></button></div>{tab === 'overview' ? <><div className="progress-track"><span>Recebimento</span><div className="progress-line"><i style={{ width: `${Math.max(10, (statuses.indexOf(order.status) / (statuses.length - 1)) * 100)}%` }} /></div><span>Entrega</span></div><OrderExecutionPanel orderId={order.id} liveMode={liveMode} notify={notify} /><div className="drawer-section"><div className="section-label"><Laptop size={16} /> Equipamento</div><div className="equipment-drawer-card"><span className="equipment-code">{device?.code}</span><div><b>{device?.brand} {device?.model}</b><span>{device?.kind} · Série {device?.serial}</span></div><ChevronRight size={17} /></div></div><div className="drawer-section"><div className="section-label"><Wrench size={16} /> Solicitação</div><p className="issue-text">{order.issue}</p><div className="detail-grid"><span><small>Responsável</small><b><Avatar name={order.technician} small /> {order.technician}</b></span><span><small>Prazo estimado</small><b className={isLate(order) ? 'late-text' : ''}>{dateLabel(order.due)} {isLate(order) && '· atrasado'}</b></span><span><small>Valor previsto</small><b>{money(order.amount)}</b></span><span><small>Saldo pendente</small><b>{money(order.amount - order.paid)}</b></span></div></div><div className="drawer-section"><div className="section-label"><MessageCircle size={16} /> Último contato</div>{order.contacts.length ? <div className="contact-note"><span className="note-channel">{order.contacts[0].channel}</span><p>{order.contacts[0].text}</p><small>{order.contacts[0].at}</small></div> : <div className="empty-note">Nenhum contato registrado ainda.<button onClick={() => notify('Registro de contato disponível na próxima etapa da fundação.')}>Registrar contato</button></div>}</div></> : <div className="timeline">{history.map((item, i) => <div className="timeline-item" key={`${item.at}-${i}`}><span className="timeline-dot" /><div><b>{item.text}</b><small>{item.at}</small></div></div>)}</div>}</div><footer className="drawer-footer"><Link className="button secondary" href={`/ordens/${order.id}/comprovante`} target="_blank">Imprimir</Link>{next && <button className="button primary" disabled={saving} onClick={advance}>{saving ? 'Atualizando…' : <>Avançar para {next} <ChevronRight size={16} /></>}</button>}</footer></aside></>; }

function OrderExecutionPanel({ orderId, liveMode, notify }: { orderId: string; liveMode: boolean; notify: (message: string, error?: boolean) => void }) { const [tasks, setTasks] = useState<Array<{ id: string; label: string; completed: boolean }>>([]); const [attachments, setAttachments] = useState<Array<{ id: string; file_name: string; url: string | null }>>([]); const [newTask, setNewTask] = useState(''); const [busy, setBusy] = useState(false); const load = useCallback(async () => { if (!liveMode) return; try { const [tasksResponse, attachmentsResponse] = await Promise.all([fetch(`/api/orders/${orderId}/tasks`), fetch(`/api/orders/${orderId}/attachments`)]); if (tasksResponse.ok) { const result = await tasksResponse.json() as { data?: Array<{ id: string; label: string; completed: boolean }> }; setTasks(result.data ?? []); } if (attachmentsResponse.ok) { const result = await attachmentsResponse.json() as { data?: Array<{ id: string; file_name: string; url: string | null }> }; setAttachments(result.data ?? []); } } catch { /* keep the drawer usable if optional details fail */ } }, [liveMode, orderId]); useEffect(() => { const timer = window.setTimeout(() => { void load(); }, 0); return () => window.clearTimeout(timer); }, [load]); async function addTask(event: React.FormEvent) { event.preventDefault(); if (!newTask.trim() || !liveMode) return; setBusy(true); try { const response = await fetch(`/api/orders/${orderId}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ label: newTask.trim(), position: tasks.length }) }); if (!response.ok) { const result = await response.json() as { error?: string }; notify(result.error ?? 'Não foi possível adicionar a atividade.', true); return; } setNewTask(''); await load(); } finally { setBusy(false); } } async function toggleTask(task: { id: string; completed: boolean }) { if (!liveMode) return; const response = await fetch(`/api/orders/${orderId}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: !task.completed }) }); if (response.ok) await load(); else notify('Não foi possível atualizar a atividade.', true); } async function upload(event: React.ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file || !liveMode) return; setBusy(true); const form = new FormData(); form.append('file', file); try { const response = await fetch(`/api/orders/${orderId}/attachments`, { method: 'POST', body: form }); const result = await response.json() as { error?: string }; if (!response.ok) notify(result.error ?? 'Não foi possível anexar o arquivo.', true); else { notify('Arquivo anexado à OS.'); await load(); } } finally { setBusy(false); event.target.value = ''; } } return <div className="drawer-section"><div className="section-label"><Check size={16} /> Execução</div>{liveMode ? <><div className="timeline">{tasks.map(task => <label className="preference" key={task.id}><span><b className={task.completed ? 'muted' : ''}>{task.label}</b><small>{task.completed ? 'Concluída' : 'Pendente'}</small></span><input type="checkbox" checked={task.completed} onChange={() => void toggleTask(task)} /></label>)}</div><form className="inline-form" onSubmit={addTask}><input value={newTask} onChange={event => setNewTask(event.target.value)} placeholder="Adicionar atividade ou teste" /><button className="button secondary compact" disabled={busy || !newTask.trim()}>Adicionar</button></form><label className="button secondary compact" style={{ display: 'inline-flex', marginTop: 10, cursor: 'pointer' }}>{busy ? 'Enviando…' : 'Anexar arquivo'}<input type="file" hidden accept="image/jpeg,image/png,image/webp,application/pdf,text/plain" onChange={upload} disabled={busy} /></label>{attachments.length > 0 && <div className="contact-note">{attachments.map(file => file.url ? <a href={file.url} target="_blank" rel="noreferrer" key={file.id}>{file.file_name}</a> : <span key={file.id}>{file.file_name}</span>)}</div>}</> : <div className="empty-note">Checklist e anexos ficam disponíveis quando a OS estiver conectada ao Supabase.</div>}</div>; }

function NewOrderModal({ data, liveMode = false, onCreated, close, notify }: { data: ReturnType<typeof useDemo>['data']; liveMode?: boolean; onCreated?: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { const { commit } = useDemo(); const [mode, setMode] = useState<Mode>('Balcão'); const [clientId, setClientId] = useState(data.clients[0]?.id ?? ''); const [deviceId, setDeviceId] = useState(data.devices[0]?.id ?? ''); const [issue, setIssue] = useState(''); const [saving, setSaving] = useState(false); const filteredDevices = data.devices.filter(d => d.clientId === clientId); async function submit(event: React.FormEvent) { event.preventDefault(); if (!clientId || !deviceId || issue.trim().length < 8) { notify('Informe cliente, equipamento e descreva o problema em pelo menos 8 caracteres.', true); return; } setSaving(true); if (liveMode) { try { const response = await fetch('/api/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ clientId, deviceId, mode, priority: 'Normal', issue: issue.trim(), dueDate: DEMO_DATE }) }); const result = await response.json() as { data?: { number: string }; error?: string }; if (!response.ok) return notify(result.error ?? 'Não foi possível abrir a OS.', true); notify(`${result.data?.number ?? 'OS'} criada. A equipe já pode iniciar o atendimento.`); onCreated?.(); close(); } catch { notify('Não foi possível conectar ao servidor.', true); } finally { setSaving(false); } return; } const nextNumber = `OS-2026-${1250 + data.orders.length}`; const success = commit(current => ({ ...current, orders: [{ id: `o-${Date.now()}`, number: nextNumber, clientId, deviceId, mode, status: 'Recebido', priority: 'Normal', technician: 'Rafael Costa', issue: issue.trim(), due: DEMO_DATE, amount: 0, paid: 0, accessories: '', history: [{ text: 'Atendimento aberto na unidade Matriz · Centro.', at: nowLabel() }], contacts: [] }, ...current.orders] }), `${nextNumber} criada. A equipe já pode iniciar o atendimento.`); setSaving(false); if (success) close(); } return <Modal title="Abrir novo atendimento" description="Comece com os dados essenciais. Você poderá complementar a OS depois." close={close}><form onSubmit={submit}><div className="modal-step"><span className="step-number">1</span><div><b>Como será o atendimento?</b><small>Escolha a modalidade para orientar os próximos passos.</small></div></div><div className="mode-picker">{(['Balcão', 'Remoto', 'Domicílio'] as Mode[]).map(option => { const Icon = modeIcon[option]; return <button type="button" className={mode === option ? 'selected' : ''} onClick={() => setMode(option)} key={option}><Icon size={19} /><b>{option}</b><small>{option === 'Balcão' ? 'Na unidade' : option === 'Remoto' ? 'Sessão online' : 'No endereço'}</small></button>; })}</div><div className="form-grid"><label>Cliente<select value={clientId} onChange={e => { setClientId(e.target.value); const next = data.devices.find(d => d.clientId === e.target.value); setDeviceId(next?.id ?? ''); }}><option value="">Selecione</option>{data.clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Equipamento<select value={deviceId} onChange={e => setDeviceId(e.target.value)}><option value="">Selecione</option>{filteredDevices.map(d => <option key={d.id} value={d.id}>{d.code} · {d.brand} {d.model}</option>)}</select></label></div><label className="full-label">Defeito relatado<textarea value={issue} onChange={e => setIssue(e.target.value)} placeholder="Ex.: notebook não liga desde ontem e faz um ruído ao conectar o carregador." rows={4} /></label><div className="form-hint"><ShieldCheck size={16} /> O histórico será vinculado ao cliente e ao equipamento automaticamente.</div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary" disabled={saving}>{saving ? 'Salvando…' : <>Criar atendimento <ChevronRight size={16} /></>}</button></div></form></Modal>; }
function NewClientModal({ liveMode = false, onCreated, close, notify }: { liveMode?: boolean; onCreated?: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { const { commit } = useDemo(); const [saving, setSaving] = useState(false); async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const name = String(form.get('name') ?? '').trim(); const phone = String(form.get('phone') ?? '').trim(); const email = String(form.get('email') ?? '').trim(); if (name.length < 3 || phone.length < 8) return notify('Informe nome e telefone válidos.', true); setSaving(true); if (liveMode) { try { const response = await fetch('/api/clients', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fullName: name, phone, email }) }); const result = await response.json() as { data?: { full_name: string }; error?: string }; if (!response.ok) return notify(result.error ?? 'Não foi possível cadastrar o cliente.', true); notify(`Cliente ${result.data?.full_name ?? name} cadastrado.`); onCreated?.(); close(); } catch { notify('Não foi possível conectar ao servidor.', true); } finally { setSaving(false); } return; } const success = commit(current => ({ ...current, clients: [{ id: `c-${Date.now()}`, name, phone, email, address: String(form.get('address') ?? '') }, ...current.clients] }), `Cliente ${name} cadastrado.`); setSaving(false); if (success) close(); } return <Modal title="Cadastrar cliente" description="Registre os dados para acompanhar todos os atendimentos futuros." close={close}><form onSubmit={submit}><div className="form-grid"><label>Nome completo<input name="name" required placeholder="Ex.: Ana Carolina de Oliveira" /></label><label>Telefone<input name="phone" required placeholder="(11) 90000-0000" /></label><label>E-mail<input name="email" type="email" placeholder="cliente@email.com" /></label><label>Endereço<input name="address" placeholder="Rua, número · bairro" /></label></div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary" disabled={saving}>{saving ? 'Salvando…' : <>Cadastrar cliente <ChevronRight size={16} /></>}</button></div></form></Modal>; }
function NewDeviceModal({ data, liveMode = false, onCreated, close, notify }: { data: ReturnType<typeof useDemo>['data']; liveMode?: boolean; onCreated?: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { const { commit } = useDemo(); const [saving, setSaving] = useState(false); async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const clientId = String(form.get('clientId') ?? ''); const kind = String(form.get('kind') ?? 'Notebook'); const brand = String(form.get('brand') ?? '').trim(); const model = String(form.get('model') ?? '').trim(); const serial = String(form.get('serial') ?? '').trim(); if (!clientId || brand.length < 2 || model.length < 2) return notify('Informe cliente, marca e modelo.', true); setSaving(true); if (liveMode) { try { const response = await fetch('/api/devices', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ clientId, kind, brand, model, serial }) }); const result = await response.json() as { data?: { code: string }; error?: string }; if (!response.ok) return notify(result.error ?? 'Não foi possível cadastrar o equipamento.', true); notify(`Equipamento ${result.data?.code ?? ''} cadastrado.`); onCreated?.(); close(); } catch { notify('Não foi possível conectar ao servidor.', true); } finally { setSaving(false); } return; } const success = commit(current => ({ ...current, devices: [{ id: `d-${Date.now()}`, clientId, code: newCode(current.devices), brand, model, serial, kind, notes: 'Cadastro criado na demonstração.' }, ...current.devices] }), 'Equipamento cadastrado com código único.'); setSaving(false); if (success) close(); } return <Modal title="Cadastrar equipamento" description="O código visível é gerado automaticamente e permanece no histórico do cliente." close={close}><form onSubmit={submit}><div className="form-grid"><label>Cliente<select name="clientId" required><option value="">Selecione</option>{data.clients.map(c => <option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label>Tipo<select name="kind" defaultValue="Notebook"><option>Notebook</option><option>Desktop</option><option>Rede / outros</option></select></label><label>Marca<input name="brand" required placeholder="Ex.: Dell" /></label><label>Modelo<input name="model" required placeholder="Ex.: Inspiron 15" /></label><label>Número de série<input name="serial" placeholder="Opcional" /></label></div><div className="code-preview"><span>Próximo código</span><b>Gerado ao salvar</b><small>Alfabeto seguro · 4 caracteres</small></div><div className="modal-footer"><button type="button" className="button secondary" onClick={close}>Cancelar</button><button className="button primary" disabled={saving}>{saving ? 'Salvando…' : <>Cadastrar equipamento <ChevronRight size={16} /></>}</button></div></form></Modal>; }
function Modal({ title, description, close, children }: { title: string; description: string; close: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" onMouseDown={event => event.target === event.currentTarget && close()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span className="eyebrow">Nexo · demonstração</span><h2 id="modal-title">{title}</h2><p>{description}</p></div><IconButton label="Fechar janela" onClick={close}><X size={20} /></IconButton></header><div className="modal-body">{children}</div></section></div>; }
